var n=`0305-pite-me-mish`;var t=`world-0305`;var o=`XK`;var a=`southern-europe`;var r=4;var l=78;var s={en:`Pite me Mish`,ua:`Піте з м'ясом`};var g={en:`A traditional Kosovo dish made with all-purpose flour, ground beef, yellow onion, parsley. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Косово. Основні інгредієнти: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, петрушка. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,450,`g`],[`water`,240,`ml`],[`table-salt`,5,`g`],[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:9,i:[[`ground-beef`,470,`g`],[`yellow-onion`,200,`g`],[`parsley`,18,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[]},{en:`Bake in a preheated 180°C oven for about 37 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 37 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:37,i:[]}];var d={slug:n,id:t,country:`XK`,region:a,servings:4,minutes:78,title:s,text:g,steps:u};export{o as country,d as default,t as id,l as minutes,a as region,r as servings,n as slug,u as steps,g as text,s as title};